import math
import re
from typing import Union


_ALLOWED_CHARS = set("0123456789.+-*/() \t\r\n")
_MAX_LENGTH = 1000
_MAX_TOKENS = 200
_MAX_DEPTH = 100

_TOKEN_NUM = "NUM"
_TOKEN_OP = "OP"
_TOKEN_LPAREN = "LPAREN"
_TOKEN_RPAREN = "RPAREN"

_PRECEDENCE = {"+": 1, "-": 1, "*": 2, "/": 2}


def _tokenize(expr: str):
    tokens = []
    i = 0
    n = len(expr)
    while i < n:
        ch = expr[i]
        if ch in " \t\r\n":
            i += 1
            continue
        if ch.isdigit() or ch == ".":
            start = i
            dot_count = 0
            digit_count = 0
            while i < n and (expr[i].isdigit() or expr[i] == "."):
                if expr[i] == ".":
                    dot_count += 1
                    if dot_count > 1:
                        raise ValueError("Invalid number: multiple decimal points")
                else:
                    digit_count += 1
                i += 1
            if dot_count > 1:
                raise ValueError("Invalid number: multiple decimal points")
            if digit_count == 0:
                raise ValueError("Invalid number: no digits")
            num_str = expr[start:i]
            if num_str.startswith("."):
                num_str = "0" + num_str
            if num_str.endswith("."):
                num_str = num_str + "0"
            try:
                value = float(num_str)
            except ValueError:
                raise ValueError("Invalid number literal")
            if not math.isfinite(value):
                raise ValueError("Number out of range")
            if value.is_integer() and "." not in expr[start:i]:
                tokens.append((_TOKEN_NUM, int(value)))
            else:
                tokens.append((_TOKEN_NUM, value))
        elif ch in "+-*/":
            tokens.append((_TOKEN_OP, ch))
            i += 1
        elif ch == "(":
            tokens.append((_TOKEN_LPAREN, ch))
            i += 1
        elif ch == ")":
            tokens.append((_TOKEN_RPAREN, ch))
            i += 1
        else:
            raise ValueError("Invalid character in expression")
        if len(tokens) > _MAX_TOKENS:
            raise ValueError("Expression too complex")
    return tokens


def _apply_unary(tokens):
    result = []
    prev_type = None
    depth = 0
    for typ, val in tokens:
        if typ == _TOKEN_OP and val in "+-":
            if prev_type is None or prev_type in (_TOKEN_OP, _TOKEN_LPAREN):
                result.append((_TOKEN_NUM, 0))
                result.append((_TOKEN_OP, val))
                prev_type = _TOKEN_OP
                continue
        if typ == _TOKEN_LPAREN:
            depth += 1
            if depth > _MAX_DEPTH:
                raise ValueError("Expression nesting too deep")
        elif typ == _TOKEN_RPAREN:
            depth -= 1
            if depth < 0:
                raise ValueError("Mismatched parentheses")
        result.append((typ, val))
        prev_type = typ
    if depth != 0:
        raise ValueError("Mismatched parentheses")
    return result


def _to_rpn(tokens):
    output = []
    stack = []
    for typ, val in tokens:
        if typ == _TOKEN_NUM:
            output.append((typ, val))
        elif typ == _TOKEN_OP:
            while stack and stack[-1][0] == _TOKEN_OP and _PRECEDENCE[stack[-1][1]] >= _PRECEDENCE[val]:
                output.append(stack.pop())
            stack.append((typ, val))
        elif typ == _TOKEN_LPAREN:
            stack.append((typ, val))
        elif typ == _TOKEN_RPAREN:
            found = False
            while stack:
                top = stack.pop()
                if top[0] == _TOKEN_LPAREN:
                    found = True
                    break
                output.append(top)
            if not found:
                raise ValueError("Mismatched parentheses")
    while stack:
        top = stack.pop()
        if top[0] in (_TOKEN_LPAREN, _TOKEN_RPAREN):
            raise ValueError("Mismatched parentheses")
        output.append(top)
    return output


def _evaluate_rpn(rpn):
    stack = []
    for typ, val in rpn:
        if typ == _TOKEN_NUM:
            stack.append(val)
        elif typ == _TOKEN_OP:
            if len(stack) < 2:
                raise ValueError("Invalid expression")
            b = stack.pop()
            a = stack.pop()
            if val == "+":
                stack.append(a + b)
            elif val == "-":
                stack.append(a - b)
            elif val == "*":
                stack.append(a * b)
            elif val == "/":
                if b == 0:
                    raise ValueError("Division by zero")
                stack.append(a / b)
            else:
                raise ValueError("Invalid operator")
    if len(stack) != 1:
        raise ValueError("Invalid expression")
    result = stack[0]
    if isinstance(result, bool):
        raise ValueError("Invalid result type")
    if not isinstance(result, (int, float)):
        raise ValueError("Invalid result type")
    if isinstance(result, float) and not math.isfinite(result):
        raise ValueError("Result out of range")
    return result


def calculate_user_input(expr: str) -> Union[int, float]:
    if not isinstance(expr, str):
        raise ValueError("Expression must be a string")
    if not expr.strip():
        raise ValueError("Expression must not be empty")
    if len(expr) > _MAX_LENGTH:
        raise ValueError("Expression too long")
    for ch in expr:
        if ch not in _ALLOWED_CHARS:
            raise ValueError("Invalid character in expression")
    try:
        tokens = _tokenize(expr)
        if not tokens:
            raise ValueError("Expression must not be empty")
        tokens = _apply_unary(tokens)
        # Validate token structure: must alternate num / op with parens allowed
        rpn = _to_rpn(tokens)
        result = _evaluate_rpn(rpn)
        return result
    except ValueError:
        raise
    except ZeroDivisionError:
        raise ValueError("Division by zero")
    except Exception:
        raise ValueError("Invalid expression")

