_MAX_EXPR_LENGTH = 1000
_ALLOWED_CHARS = set("0123456789.+-*/() \t\r\n")


def _validate_chars(expr: str) -> None:
    for ch in expr:
        if ch not in _ALLOWED_CHARS:
            raise ValueError("invalid character in expression: {!r}".format(ch))


def _tokenize(expr: str):
    tokens = []
    i = 0
    n = len(expr)
    while i < n:
        ch = expr[i]
        if ch.isspace():
            i += 1
            continue
        if ch.isdigit() or ch == '.':
            start = i
            seen_dot = False
            while i < n and (expr[i].isdigit() or expr[i] == '.'):
                if expr[i] == '.':
                    if seen_dot:
                        raise ValueError("invalid number: multiple decimal points")
                    seen_dot = True
                i += 1
            text = expr[start:i]
            if text == '.':
                raise ValueError("invalid number: '.'")
            if seen_dot and not any(c.isdigit() for c in text):
                raise ValueError("invalid number")
            if seen_dot:
                tokens.append(('num', float(text)))
            else:
                tokens.append(('num', int(text)))
            continue
        if ch in '+-*/()':
            tokens.append((ch, ch))
            i += 1
            continue
        raise ValueError("invalid character: {!r}".format(ch))
    return tokens


class _Parser:
    def __init__(self, tokens):
        self.tokens = tokens
        self.pos = 0

    def _peek(self):
        if self.pos < len(self.tokens):
            return self.tokens[self.pos]
        return (None, None)

    def _advance(self):
        tok = self.tokens[self.pos]
        self.pos += 1
        return tok

    def _expect(self, kind):
        tok = self._peek()
        if tok[0] != kind:
            raise ValueError("expected {!r} but found {!r}".format(kind, tok[0]))
        return self._advance()

    def parse(self):
        if not self.tokens:
            raise ValueError("empty expression")
        value = self._expression()
        if self.pos != len(self.tokens):
            raise ValueError("unexpected token: {!r}".format(self.tokens[self.pos][0]))
        return value

    def _expression(self):
        # expression := term (('+' | '-') term)*
        value, is_int = self._term()
        while True:
            kind, _ = self._peek()
            if kind in ('+', '-'):
                self._advance()
                rhs, rhs_int = self._term()
                if kind == '+':
                    value = value + rhs
                else:
                    value = value - rhs
                is_int = is_int and rhs_int and (isinstance(value, int) or value == int(value))
                if isinstance(value, float) and is_int:
                    value = int(value)
            else:
                break
        return value, is_int

    def _term(self):
        # term := factor (('*' | '/') factor)*
        value, is_int = self._factor()
        while True:
            kind, _ = self._peek()
            if kind in ('*', '/'):
                self._advance()
                rhs, rhs_int = self._factor()
                if kind == '*':
                    value = value * rhs
                    is_int = is_int and rhs_int and (isinstance(value, int) or value == int(value))
                    if isinstance(value, float) and is_int:
                        value = int(value)
                else:
                    if rhs == 0:
                        raise ValueError("division by zero")
                    value = value / rhs
                    is_int = False
            else:
                break
        return value, is_int

    def _factor(self):
        # factor := ('+' | '-') factor | number | '(' expression ')'
        kind, _ = self._peek()
        if kind == '+':
            self._advance()
            return self._factor()
        if kind == '-':
            self._advance()
            value, is_int = self._factor()
            return -value, is_int
        if kind == 'num':
            self._advance()
            v = self.tokens[self.pos - 1][1]
            return v, isinstance(v, int)
        if kind == '(':
            self._advance()
            value, is_int = self._expression()
            self._expect(')')
            return value, is_int
        raise ValueError("unexpected token: {!r}".format(kind))


def calculate_user_input(expr: str):
    if not isinstance(expr, str):
        raise ValueError("expression must be a string")
    stripped = expr.strip()
    if not stripped:
        raise ValueError("empty expression")
    if len(expr) > _MAX_EXPR_LENGTH:
        raise ValueError("expression too long")

    _validate_chars(expr)

